// The widths of the characters of every font a text style may have, for a text of height 1 and
// width factor 1. The numbers are data: do not edit them by hand.

/** One font, for a text of height 1 and width factor 1. */
export interface FontMetrics {
  /** How far below the baseline the bottom of a text is. */
  readonly below: number;
  /** How far each character of `FONT_METRICS_RANGES` moves the next one along. */
  readonly advances: readonly number[];
  /**
   * What the last character of a text adds to its length beyond the advances before it, less
   * its own advance.
   */
  readonly tails: readonly number[];
  /** Where the first character of a text starts to draw, from the text's first point. */
  readonly heads: readonly number[];
  /**
   * Where a line of paragraph text that starts with the character starts to draw, from the
   * character's first point: the left of its ink, and never before that point. 0 for a space.
   */
  readonly lefts: readonly number[];
  /**
   * Where the character's ink ends, from its first point: past its advance for a letter that
   * overhangs it. A space's is its advance.
   */
  readonly rights: readonly number[];
  /**
   * How far above the baseline the character raises a line of paragraph text: the top of its
   * ink, and never less than 1. A mark that lies wholly above the baseline in a TrueType font,
   * such as a degree sign, raises the line by 1.
   */
  readonly tops: readonly number[];
  /**
   * Where the bottom of a paragraph's box lies, from the baseline, when the character is in the
   * paragraph's last line: the bottom of its ink, and never above the baseline.
   */
  readonly bottoms: readonly number[];
  /**
   * How far the top of a stack stands above the baseline of its top part where that part is the
   * character alone: the height of its ink, top less bottom, below 1 for a figure lower than a
   * capital. 0 for a space.
   */
  readonly stackTops: readonly number[];
  /**
   * How far past the end of a stacked fraction's ink the next character's first point lies, for
   * a stack of height 1.
   */
  readonly afterStack: number;
  /** For a TrueType font, its bold face. */
  readonly bold?: FontFace;
}

/**
 * A face of a font: its own advances and ink, as `FontMetrics` holds the regular face's, for
 * the face drawn so that its own capital A is as tall as the text's height.
 */
export interface FontFace {
  readonly advances: readonly number[];
  readonly lefts: readonly number[];
  readonly rights: readonly number[];
  readonly tops: readonly number[];
  readonly bottoms: readonly number[];
}

